const $=(s,r=document)=>r.querySelector(s)
const $$=(s,r=document)=>[...r.querySelectorAll(s)]
const state={accounts:[],overview:null,update:null,networkSample:null,page:'overview'}
const protocols=['vless','vmess','trojan','shadowsocks','socks','http']

function fmtBytes(n,rate=false){n=Number(n||0);const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}const d=n>=100||i===0?0:n>=10?1:2;return `${n.toFixed(d)} ${u[i]}${rate?'/s':''}`}
function fmtPercent(a,b){return b?Math.round(Number(a)/Number(b)*100):0}
function fmtUptime(sec){sec=Math.max(0,Number(sec||0));const d=Math.floor(sec/86400),h=Math.floor(sec%86400/3600),m=Math.floor(sec%3600/60);return `${d} 天 ${h} 小时 ${m} 分`}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(msg,bad=false){const e=$('#toast');e.textContent=msg;e.classList.remove('hidden');e.classList.toggle('bad',bad);clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.add('hidden'),3000)}
function reasonText(a){if(a.enabled)return '运行中';return ({quota:'流量额度已用完',expiry:'已到期',manual:'手动停用'})[a.disabledReason]||'已停用'}
function formValue(form,name){return new FormData(form).get(name)??''}

async function api(path,options={}){const opts={credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}};const res=await fetch(path,opts);let data=null;const ct=res.headers.get('content-type')||'';if(ct.includes('application/json')){try{data=await res.json()}catch{}}if(!res.ok){const err=new Error(data?.error||`HTTP ${res.status}`);err.status=res.status;throw err}return data}

async function boot(){bind();try{await loadOverview();showApp()}catch(e){showLogin();if(e.status!==401){$('#login-error').textContent=e.message;$('#login-error').classList.remove('hidden')}}}
function showLogin(){$('#login').classList.remove('hidden');$('#app').classList.add('hidden');setTimeout(()=>$('#login-pass').focus(),20)}
function showApp(){$('#login').classList.add('hidden');$('#app').classList.remove('hidden');void loadAccounts();void checkUpdate()}
function overviewPollingActive(){return !document.hidden&&!$('#app').classList.contains('hidden')&&(state.page==='overview'||state.page==='xray')}

function bind(){
 $('#login-form').addEventListener('submit',async e=>{e.preventDefault();const out=$('#login-error');out.classList.add('hidden');try{await api('/api/login',{method:'POST',body:JSON.stringify({username:$('#login-user').value,password:$('#login-pass').value})});$('#login-pass').value='';await loadOverview();showApp()}catch(x){out.textContent=x.message;out.classList.remove('hidden')}})
 $$('#nav button').forEach(b=>b.addEventListener('click',()=>switchPage(b.dataset.page)))
 $('#refresh-overview').onclick=()=>loadOverview(true)
 $('#add-account').onclick=()=>openAccountModal()
 $('#modal-close').onclick=closeModal
 $('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()})
 $('#check-update').onclick=()=>checkUpdate(true);$('#do-update').onclick=updateXray;$('#xray-page-update').onclick=async()=>{await checkUpdate(true);if(state.update?.available)await updateXray()}
 $('#restart-xray').onclick=restartXray;$('#load-logs').onclick=loadLogs;$('#download-logs').onclick=downloadLogs
 $('#settings-form').onsubmit=saveSettings;$('#create-backup').onclick=createBackup
 setInterval(()=>{if(overviewPollingActive())void loadOverview(false,true)},10000)
 document.addEventListener('visibilitychange',()=>{if(overviewPollingActive())void loadOverview(false,true)})
}
function switchPage(page){state.page=page;$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${page}`));if(page==='accounts')void loadAccounts();if(page==='overview'||page==='xray')void loadOverview();if(page==='xray')void loadLogs();if(page==='system'){void loadSettings();void loadBackups()}}

async function loadOverview(manual=false,silent=false){try{const d=await api('/api/overview'),now=Date.now(),sys=d.system||{},prev=state.networkSample;state.overview=d;state.networkSample={t:now,rx:Number(sys.networkRx||0),tx:Number(sys.networkTx||0)};$('#hostname').textContent=sys.hostname||'Linux node';$('#uptime-days').textContent=Math.floor(Number(sys.uptimeSeconds||0)/86400);$('#uptime-text').textContent=fmtUptime(sys.uptimeSeconds);$('#server-os').textContent=`${sys.os||'Linux'} · ${d.accounts?.enabled||0} 个独立监听端口`;$('#cpu').textContent=`${Number(sys.cpuPercent||0).toFixed(1)}%`;$('#load').textContent=`load ${Number(sys.load1||0).toFixed(2)}`;$('#memory').textContent=`${fmtPercent(sys.memoryUsed,sys.memoryTotal)}%`;$('#memory-detail').textContent=`${fmtBytes(sys.memoryUsed)} / ${fmtBytes(sys.memoryTotal)}`;$('#disk').textContent=`${fmtPercent(sys.diskUsed,sys.diskTotal)}%`;$('#disk-detail').textContent=`${fmtBytes(sys.diskUsed)} / ${fmtBytes(sys.diskTotal)}`;$('#listeners').textContent=d.accounts?.enabled??0;$('#xray-version').textContent=sys.xrayVersion?`v${String(sys.xrayVersion).replace(/^v/,'')}`:'—';$('#xport-version').textContent=d.xportVersion||'—';$('#xray-desc').textContent=`代理核心 · ${d.accounts?.enabled||0} 个 inbound`;setServiceStatus(Boolean(sys.xrayActive));if(prev){const sec=Math.max(.2,(now-prev.t)/1000),rx=Math.max(0,(Number(sys.networkRx||0)-prev.rx)/sec),tx=Math.max(0,(Number(sys.networkTx||0)-prev.tx)/sec);$('#rx-rate').textContent=fmtBytes(rx,true);$('#tx-rate').textContent=fmtBytes(tx,true);$('#traffic-total').textContent=fmtBytes(rx+tx,true)}if(manual)toast('服务器状态已刷新')}catch(e){if(e.status===401){showLogin();return}if(!silent)toast(e.message,true);throw e}}
function setServiceStatus(active){const a=$('#xray-status'),h=$('#health-xray');a.className=`status ${active?'ok':'bad'}`;a.innerHTML=`<i></i>${active?'运行中':'异常'}`;h.className=active?'ok-text':'bad-text';h.textContent=`● ${active?'正常':'异常'}`;$('#health-listeners').textContent=`${state.overview?.accounts?.enabled||0} / ${state.overview?.accounts?.total||0}`;$('#health-listeners').className='ok-text';$('#xray-page-status').textContent=active?'运行中':'异常';$('#xray-page-version').textContent=state.overview?.system?.xrayVersion?`Xray ${state.overview.system.xrayVersion}`:'版本未知';$('#xray-page-dot').style.background=active?'var(--green)':'var(--red)'}

async function loadAccounts(){try{const d=await api('/api/accounts');state.accounts=d.accounts||[];renderAccounts()}catch(e){if(e.status===401)showLogin();else toast(e.message,true)}}
function renderAccounts(){const arr=state.accounts,list=$('#accounts-list');$('#sum-total').textContent=arr.length;$('#sum-active').textContent=arr.filter(a=>a.enabled).length;$('#sum-traffic').textContent=fmtBytes(arr.reduce((n,a)=>n+Number(a.upBytes||0)+Number(a.downBytes||0),0));$('#sum-monthly').textContent=arr.filter(a=>a.monthlyReset).length;if(!arr.length){list.innerHTML='<div class="empty"><b>还没有账号</b><span>新增账号，或通过迁移脚本导入 X-Panel / 3x-ui。</span></div>';return}list.innerHTML=arr.map(a=>{const used=Number(a.upBytes||0)+Number(a.downBytes||0),quota=Number(a.quotaBytes||0),pct=quota?Math.min(100,Math.round(used/quota*100)):0,editable=Boolean(a.editable);return `<article class="account-row" data-id="${a.id}"><div class="account-name"><i class="state ${a.enabled?'on':''}"></i><div><b>${esc(a.name)}</b><small>${esc(reasonText(a))} · ID ${a.id}${a.monthlyReset?' · 每月1日清零':''}</small></div></div><div class="port-cell"><span class="tag">:${a.port}</span></div><div class="protocol-cell hide-mid"><span class="tag">${esc(String(a.protocol||'').toUpperCase())}${a.security?` · ${esc(String(a.security).toUpperCase())}`:''}</span></div><div class="usage-cell hide-mid"><small>本期 ${quota?`/ ${fmtBytes(quota)}`:'· 不限'}</small><b>${fmtBytes(used)}</b><div class="mini-bar"><i style="width:${pct}%"></i></div></div><div class="hide-mid"><small class="muted tiny">${a.expiryTime?new Date(a.expiryTime).toLocaleDateString():'永久'}</small></div><div class="row-actions"><button class="icon-btn" data-act="reset" title="清零本期流量">↺</button><button class="icon-btn" data-act="share" title="分享" ${editable?'':'disabled'}>⌁</button><button class="icon-btn" data-act="clone" title="克隆" ${editable?'':'disabled'}>⧉</button><button class="icon-btn" data-act="edit" title="编辑">✎</button><button class="icon-btn" data-act="delete" title="删除">×</button></div></article>`}).join('');$$('.account-row').forEach(row=>row.onclick=e=>{const b=e.target.closest('button[data-act]');if(!b||b.disabled)return;const id=Number(row.dataset.id);({edit:()=>openAccountModal(state.accounts.find(a=>a.id===id)),clone:()=>openCloneModal(id),delete:()=>deleteAccount(id),share:()=>openShareModal(id),reset:()=>resetTraffic(id)})[b.dataset.act]?.()})}

function openModal(html){$('#modal-body').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden');$('#modal-body').innerHTML=''}
function option(v,label,current){return `<option value="${v}" ${current===v?'selected':''}>${label}</option>`}
function commonAccountFields(a){const expiry=a.expiryTime?new Date(Number(a.expiryTime)-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'',qgb=a.quotaBytes?(Number(a.quotaBytes)/1073741824).toFixed(2):'';return `<label>账号名<input name="name" value="${esc(a.name||'')}" required maxlength="80"></label><label>独立端口<input name="port" type="number" min="1" max="65535" value="${a.port||''}" placeholder="留空自动分配"></label><label>流量上限 / GB<input name="quota" type="number" min="0" step="0.1" value="${qgb}" placeholder="0 = 不限"></label><label>到期时间<input name="expiry" type="datetime-local" value="${expiry}"></label><label class="checkline"><input name="enabled" type="checkbox" ${a.id?(a.enabled?'checked':''):'checked'}>启用账号</label><label class="checkline"><input name="monthlyReset" type="checkbox" ${a.monthlyReset?'checked':''}>每月 1 日自动清零本期流量</label><p class="muted tiny full">月初清零只重置本期上下行，累计总流量保留；如果账号因额度耗尽被自动停用，清零后自动恢复。手动停用或已到期账号不会自动开启。</p>`}
function accountFormHTML(a={}){const p=String(a.protocol||'vless').toLowerCase(),editing=Boolean(a.id);if(editing&&!a.editable){return `<div class="modal-title"><span>IMPORTED ACCOUNT</span><h2>${esc(a.name)}</h2></div><div class="readonly-note"><p>该账号使用 ${esc(p.toUpperCase())}，X-port 会继续原样运行它，但当前没有专用编辑器。</p><p class="muted tiny">为了不破坏旧 X-Panel 的高级配置，这里暂不提供修改/克隆/分享。可以安全删除或在后续版本加入对应编辑器。</p></div>`}return `<div class="modal-title"><span>${editing?'EDIT ACCOUNT':'NEW ACCOUNT'}</span><h2>${editing?'编辑账号':'新增账号'}</h2></div><form id="account-form" class="form-grid">${commonAccountFields(a)}<label>协议<select name="protocol" id="protocol-select" ${editing?'disabled':''}>${protocols.map(x=>option(x,x.toUpperCase(),p)).join('')}</select></label><div class="full proto-fields" id="proto-fields"></div><div class="form-actions full"><button type="button" class="btn ghost" id="cancel-form">取消</button><button type="submit" class="btn primary">${editing?'保存并应用':'创建并应用'}</button></div></form>`}
function protocolFields(p,a){const transport=!['socks','http'].includes(p),network=a.network||'tcp',security=a.security||(p==='vless'||p==='trojan'?'reality':'none');let cred='';if(p==='vless')cred=`<label>UUID<input name="credential" value="${esc(a.credential||'')}" placeholder="留空自动生成"></label><label>Flow<input name="flow" value="${esc(a.flow||'xtls-rprx-vision')}"></label>`;if(p==='vmess')cred=`<label>UUID<input name="credential" value="${esc(a.credential||'')}" placeholder="留空自动生成"></label><label>VMess Security<select name="clientSecurity">${['auto','aes-128-gcm','chacha20-poly1305','none','zero'].map(x=>option(x,x,a.clientSecurity||'auto')).join('')}</select></label>`;if(p==='trojan')cred=`<label>Trojan 密码<input name="password" value="${esc(a.password||'')}" placeholder="留空自动生成"></label>`;if(p==='shadowsocks')cred=`<label>加密方式<select name="method">${['chacha20-ietf-poly1305','aes-256-gcm','2022-blake3-aes-256-gcm','2022-blake3-chacha20-poly1305'].map(x=>option(x,x,a.method||'chacha20-ietf-poly1305')).join('')}</select></label><label>服务器密码<input name="serverPassword" value="${esc(a.serverPassword||'')}" placeholder="留空自动生成"></label><label>客户端密码<input name="password" value="${esc(a.password||'')}" placeholder="留空自动生成"></label>`;if(p==='socks'||p==='http')cred=`<label>用户名<input name="username" value="${esc(a.username||'')}"></label><label>密码<input name="password" value="${esc(a.password||'')}" placeholder="留空自动生成"></label>`;if(!transport)return `<div class="advanced-grid">${cred}</div>`;const allowedSecurity=(p==='vless'||p==='trojan')?['none','tls','reality']:['none','tls'];return `<div class="advanced-grid">${cred}<label>传输<select name="network" id="network-select">${['tcp','ws','grpc','httpupgrade','xhttp'].map(x=>option(x,x,network)).join('')}</select></label><label>传输安全<select name="security" id="security-select">${allowedSecurity.map(x=>option(x,x,security)).join('')}</select></label><label class="transport-host">Host<input name="host" value="${esc(a.host||'')}"></label><label class="transport-path">Path<input name="path" value="${esc(a.path||'')}" placeholder="/"></label><label class="transport-service">gRPC Service<input name="serviceName" value="${esc(a.serviceName||'')}"></label><label class="tls-sni">SNI<input name="serverName" value="${esc(a.serverName||'')}"></label><div class="reality-fields full"><div class="advanced-grid"><label>REALITY 目标<input name="dest" value="${esc(a.dest||'')}" placeholder="example.com:443"></label><label>Private Key<input name="privateKey" value="${esc(a.privateKey||'')}" placeholder="留空自动生成"></label><label>Short ID<input name="shortId" value="${esc(a.shortId||'')}" placeholder="留空自动生成"></label></div></div></div>`}
function refreshProtocolFields(full){const p=$('#protocol-select')?.value||full.protocol||'vless',box=$('#proto-fields');if(!box)return;box.innerHTML=protocolFields(p,full);const net=$('#network-select'),sec=$('#security-select');const tune=()=>{const n=net?.value||'tcp',s=sec?.value||'none';$$('.transport-host',box).forEach(e=>e.style.display=['ws','httpupgrade','xhttp'].includes(n)?'grid':'none');$$('.transport-path',box).forEach(e=>e.style.display=['ws','httpupgrade','xhttp'].includes(n)?'grid':'none');$$('.transport-service',box).forEach(e=>e.style.display=n==='grpc'?'grid':'none');$$('.tls-sni',box).forEach(e=>e.style.display=(s==='tls'||s==='reality')?'grid':'none');$$('.reality-fields',box).forEach(e=>e.style.display=s==='reality'?'block':'none')};net?.addEventListener('change',tune);sec?.addEventListener('change',tune);tune()}
async function openAccountModal(a=null){let full=a||{};if(a?.id){try{full=await api(`/api/accounts/${a.id}`)}catch(e){toast(e.message,true);return}}openModal(accountFormHTML(full));if(full.id&&!full.editable)return;$('#cancel-form').onclick=closeModal;refreshProtocolFields(full);$('#protocol-select')?.addEventListener('change',()=>{const p=$('#protocol-select').value;full={...full,protocol:p,credential:'',username:'',password:'',serverPassword:'',privateKey:'',shortId:'',serverName:'',dest:'',host:'',path:'',serviceName:'',network:'tcp',security:(p==='vless'||p==='trojan')?'reality':'none'};refreshProtocolFields(full)});$('#account-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,p=full.id?full.protocol:formValue(f,'protocol');const body={name:formValue(f,'name'),enabled:new FormData(f).get('enabled')==='on',monthlyReset:new FormData(f).get('monthlyReset')==='on',port:Number(formValue(f,'port')||0),protocol:p,credential:formValue(f,'credential'),username:formValue(f,'username'),password:formValue(f,'password'),serverPassword:formValue(f,'serverPassword'),clientSecurity:formValue(f,'clientSecurity'),method:formValue(f,'method'),flow:formValue(f,'flow'),network:formValue(f,'network'),security:formValue(f,'security'),serverName:formValue(f,'serverName'),dest:formValue(f,'dest'),privateKey:formValue(f,'privateKey'),shortId:formValue(f,'shortId'),host:formValue(f,'host'),path:formValue(f,'path'),serviceName:formValue(f,'serviceName'),quotaBytes:Math.round(Number(formValue(f,'quota')||0)*1073741824),expiryTime:formValue(f,'expiry')?new Date(formValue(f,'expiry')).getTime():0};const b=f.querySelector('button[type=submit]');b.disabled=true;b.textContent='应用中…';try{if(full.id)await api(`/api/accounts/${full.id}`,{method:'PUT',body:JSON.stringify(body)});else await api('/api/accounts',{method:'POST',body:JSON.stringify(body)});closeModal();await loadAccounts();await loadOverview();toast(full.id?'账号已更新':'账号已创建')}catch(x){toast(x.message,true);b.disabled=false;b.textContent=full.id?'保存并应用':'创建并应用'}}}
function openCloneModal(id){const a=state.accounts.find(x=>x.id===id);openModal(`<div class="modal-title"><span>CLONE ACCOUNT</span><h2>克隆 ${esc(a?.name||'账号')}</h2></div><form id="clone-form" class="form-grid"><label>新账号名<input name="name" value="${esc((a?.name||'account')+' copy')}" required></label><label>新端口<input name="port" type="number" min="1" max="65535" placeholder="留空自动分配"></label><p class="muted tiny full">协议与传输参数会复制；UUID/密码自动重新生成，本期与累计流量清零。</p><div class="form-actions full"><button type="button" class="btn ghost" id="clone-cancel">取消</button><button class="btn primary" type="submit">克隆并应用</button></div></form>`);$('#clone-cancel').onclick=closeModal;$('#clone-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/accounts/${id}/clone`,{method:'POST',body:JSON.stringify({name:f.get('name'),port:Number(f.get('port')||0)})});closeModal();await loadAccounts();await loadOverview();toast('账号已克隆')}catch(x){toast(x.message,true)}}}
async function resetTraffic(id){const a=state.accounts.find(x=>x.id===id);if(!confirm(`清零「${a?.name||id}」的本期上下行流量？\n累计总流量不会清零。`))return;try{await api(`/api/accounts/${id}/traffic/reset`,{method:'POST',body:'{}'});await loadAccounts();await loadOverview();toast('本期流量已清零')}catch(e){toast(e.message,true)}}
async function deleteAccount(id){const a=state.accounts.find(x=>x.id===id);if(!confirm(`删除账号「${a?.name||id}」？\n对应 inbound 会从 Xray 配置移除。`))return;try{await api(`/api/accounts/${id}`,{method:'DELETE'});await loadAccounts();await loadOverview();toast('账号已删除')}catch(e){toast(e.message,true)}}
async function openShareModal(id){const a=state.accounts.find(x=>x.id===id),defaultHost=location.hostname;openModal(`<div class="modal-title"><span>SHARE</span><h2>${esc(a?.name||'账号')} · 分享</h2></div><div class="share-wrap"><div class="qr-box"><img id="share-qr" alt="QR code"></div><div class="share-side"><label>服务器域名 / IP<input id="share-host" value="${esc(defaultHost)}"></label><label>分享链接<textarea id="share-link" class="share-link" readonly></textarea></label><div class="button-row"><button id="copy-share" class="btn primary">复制链接</button><button id="reload-share" class="btn ghost">刷新</button></div></div></div>`);async function refresh(){const host=$('#share-host').value.trim();try{const d=await api(`/api/accounts/${id}/share?host=${encodeURIComponent(host)}`);$('#share-link').value=d.uri;$('#share-qr').src=`/api/accounts/${id}/qr?host=${encodeURIComponent(host)}&t=${Date.now()}`}catch(e){toast(e.message,true)}}$('#reload-share').onclick=refresh;$('#share-host').onchange=refresh;$('#copy-share').onclick=async()=>{await navigator.clipboard.writeText($('#share-link').value);toast('分享链接已复制')};await refresh()}

async function checkUpdate(manual=false){const latest=$('#update-latest'),note=$('#update-note'),btn=$('#do-update');latest.textContent='检查中';btn.disabled=true;try{const d=await api('/api/xray/update');state.update=d;$('#update-current').textContent=d.current?`v${String(d.current).replace(/^v/,'')}`:'未安装';latest.textContent=d.latest?`v${String(d.latest).replace(/^v/,'')}`:'—';note.textContent=d.available?`发现${d.prerelease?'预发布':''}新版本 · ${d.asset}`:'当前已是最新版本';btn.disabled=!d.available;btn.textContent=d.available?'更新 Xray':'已是最新';if(manual)toast(d.available?'发现可用更新':'Xray 已是最新')}catch(e){latest.textContent='检查失败';note.textContent=e.message;if(manual)toast(e.message,true)}}
async function updateXray(){if(!state.update?.available){await checkUpdate(true);if(!state.update?.available)return}if(!confirm(`将 Xray 从 ${state.update.current||'当前版本'} 更新到 ${state.update.latest}。\n新核心会先测试当前配置，失败自动回滚。继续吗？`))return;const b=$('#do-update');b.disabled=true;b.textContent='更新中…';try{const d=await api('/api/xray/update',{method:'POST',body:'{}'});state.update=d;toast(`Xray 已更新到 ${d.current}`);await loadOverview();await checkUpdate()}catch(e){toast(e.message,true);b.disabled=false;b.textContent='重试更新'}}
async function restartXray(){if(!confirm('重启 Xray 服务？现有连接可能短暂中断。'))return;try{await api('/api/xray/restart',{method:'POST',body:'{}'});toast('Xray 已重启');setTimeout(()=>loadOverview(),1000)}catch(e){toast(e.message,true)}}
async function loadLogs(){try{const service=$('#log-service').value,lines=$('#log-lines').value,d=await api(`/api/logs?service=${encodeURIComponent(service)}&lines=${lines}`);$('#log-output').textContent=d.logs||'(无日志)'}catch(e){$('#log-output').textContent=e.message;toast(e.message,true)}}
function downloadLogs(){const service=$('#log-service').value,lines=$('#log-lines').value;location.href=`/api/logs?service=${encodeURIComponent(service)}&lines=${lines}&download=1`}

async function loadSettings(){try{const d=await api('/api/settings'),f=$('#settings-form');for(const [k,v] of Object.entries(d)){const el=f.elements.namedItem(k);if(el)el.value=v??''}f.elements.currentPassword.value='';f.elements.newPassword.value=''}catch(e){toast(e.message,true)}}
async function saveSettings(e){e.preventDefault();const f=e.currentTarget,body={panelListen:formValue(f,'panelListen'),xrayApiPort:Number(formValue(f,'xrayApiPort')),portMin:Number(formValue(f,'portMin')),portMax:Number(formValue(f,'portMax')),defaultRealitySni:formValue(f,'defaultRealitySni'),defaultRealityDest:formValue(f,'defaultRealityDest'),adminUsername:formValue(f,'adminUsername'),currentPassword:formValue(f,'currentPassword'),newPassword:formValue(f,'newPassword')};try{const d=await api('/api/settings',{method:'PUT',body:JSON.stringify(body)});f.elements.currentPassword.value='';f.elements.newPassword.value='';toast(d.restartRequired?'设置已保存；相关监听设置重启 X-port 后生效':'设置已保存')}catch(x){toast(x.message,true)}}
async function loadBackups(){try{const d=await api('/api/backups'),list=$('#backup-list'),arr=d.backups||[];if(!arr.length){list.innerHTML='<div class="empty small"><b>暂无手动备份</b></div>';return}list.innerHTML=arr.map(x=>`<div class="backup-row" data-name="${esc(x.name)}"><div><b>${esc(x.name)}</b><small>${new Date(x.createdAt).toLocaleString()} · ${fmtBytes(x.size)}</small></div><div class="row-actions"><button class="icon-btn" data-act="download" title="下载">↓</button><button class="icon-btn" data-act="restore" title="恢复">↺</button><button class="icon-btn" data-act="delete" title="删除">×</button></div></div>`).join('');$$('.backup-row').forEach(row=>row.onclick=e=>{const b=e.target.closest('button[data-act]');if(!b)return;const n=row.dataset.name;if(b.dataset.act==='download')location.href=`/api/backups/${encodeURIComponent(n)}/download`;if(b.dataset.act==='restore')void restoreBackup(n);if(b.dataset.act==='delete')void deleteBackup(n)})}catch(e){toast(e.message,true)}}
async function createBackup(){try{await api('/api/backups',{method:'POST',body:'{}'});toast('备份已创建');await loadBackups()}catch(e){toast(e.message,true)}}
async function restoreBackup(name){if(!confirm(`恢复备份 ${name}？\n恢复前会自动再创建一个当前状态快照。`))return;try{await api(`/api/backups/${encodeURIComponent(name)}/restore`,{method:'POST',body:'{}'});toast('恢复成功，请重新登录');setTimeout(()=>showLogin(),400)}catch(e){toast(e.message,true)}}
async function deleteBackup(name){if(!confirm(`删除备份 ${name}？`))return;try{await api(`/api/backups/${encodeURIComponent(name)}`,{method:'DELETE'});toast('备份已删除');await loadBackups()}catch(e){toast(e.message,true)}}

document.addEventListener('DOMContentLoaded',boot)
